#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_SESSIONS 256
#define BUFFER_SIZE 1024

typedef struct session {
    int id;
    char *username;
    char *auth_token;
    int socket_fd;
    int active;
    void (*cleanup)(struct session *);
} session_t;

session_t *session_pool[MAX_SESSIONS];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void session_cleanup(session_t *s) {
    if (s->username) free(s->username);
    if (s->auth_token) free(s->auth_token);
    close(s->socket_fd);
    free(s);
}

session_t *create_session(int fd, const char *user) {
    session_t *s = (session_t *)malloc(sizeof(session_t));
    s->username = strdup(user);
    s->auth_token = (char *)malloc(64);
    snprintf(s->auth_token, 64, "tok_%s_%d", user, rand());
    s->socket_fd = fd;
    s->active = 1;
    s->cleanup = session_cleanup;
    return s;
}

void destroy_session(int id) {
    pthread_mutex_lock(&pool_lock);
    if (id >= 0 && id < MAX_SESSIONS && session_pool[id]) {
        session_pool[id]->cleanup(session_pool[id]);
        // BUG: pointer not nullified after free
        // session_pool[id] = NULL;  // MISSING
    }
    pthread_mutex_unlock(&pool_lock);
}

void handle_admin_cmd(int id, const char *cmd) {
    // Race window: session may have been freed by another thread
    // but pointer still in pool due to missing NULL assignment
    if (id >= 0 && id < MAX_SESSIONS && session_pool[id]) {
        session_t *s = session_pool[id];
        if (s->active) {  // reads freed memory
            // Attacker can spray heap to control function pointer
            if (strcmp(cmd, "escalate") == 0) {
                // This writes a log entry to /var/log/service/audit.log
                FILE *f = fopen("/var/log/service/audit.log", "a");
                if (f) {
                    fprintf(f, "ADMIN_CMD: user=%s cmd=%s\n", s->username, cmd);
                    fclose(f);
                }
                // Invoke cleanup function pointer (UAF -> code exec)
                s->cleanup(s);
            }
        }
    }
}

void *connection_handler(void *arg) {
    int fd = *(int *)arg;
    free(arg);
    char buf[BUFFER_SIZE];
    int n = read(fd, buf, BUFFER_SIZE - 1);
    if (n <= 0) { close(fd); return NULL; }
    buf[n] = '\0';

    char *action = strtok(buf, "|");
    char *param1 = strtok(NULL, "|");
    char *param2 = strtok(NULL, "|");

    if (action && strcmp(action, "LOGIN") == 0 && param1) {
        pthread_mutex_lock(&pool_lock);
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (!session_pool[i]) {
                session_pool[i] = create_session(fd, param1);
                session_pool[i]->id = i;
                char resp[128];
                snprintf(resp, sizeof(resp), "OK|%d|%s\n", i, session_pool[i]->auth_token);
                write(fd, resp, strlen(resp));
                break;
            }
        }
        pthread_mutex_unlock(&pool_lock);
    } else if (action && strcmp(action, "LOGOUT") == 0 && param1) {
        destroy_session(atoi(param1));
    } else if (action && strcmp(action, "ADMIN") == 0 && param1 && param2) {
        handle_admin_cmd(atoi(param1), param2);
    }
    return NULL;
}

int main() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(8080), .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    while (1) {
        int *client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, NULL, NULL);
        pthread_t t;
        pthread_create(&t, NULL, connection_handler, client_fd);
        pthread_detach(t);
    }
    return 0;
}
